// Split the ESP32 telemetry JSON into one message per dashboard widget.
// Outputs: 1 temp gauge, 2 humidity gauge, 3 mode switch, 4 power switch,
//          5 setpoint slider, 6 overview state, 7 history chart,
//          8 high-temperature alert (toast), 9 activity-log events
const d = msg.payload;
if (typeof d !== 'object' || d === null) {
    node.warn('Invalid telemetry: ' + JSON.stringify(msg.payload));
    return null;
}
const hasT = typeof d.temperature === 'number';
const hasH = typeof d.humidity === 'number';

const temp  = hasT ? { payload: d.temperature } : null;
const hum   = hasH ? { payload: d.humidity } : null;
const mode  = { payload: d.mode };          // "AUTO" | "MANUAL"
const power = { payload: d.ac };            // "ON"   | "OFF"
const sp    = { payload: d.setpoint };      // number
const overview = { topic: 'telemetry', payload: d };

// Chart: one message per series (topic = series name)
const chart = [];
if (hasT) chart.push({ topic: 'Temperature (°C)', payload: d.temperature });
if (hasH) chart.push({ topic: 'Humidity (%)', payload: d.humidity });

// Alert once when temperature reaches 35 °C (re-armed when it drops below)
let alert = null;
const hot = hasT && d.temperature >= 35;
if (hot && !context.get('alerted')) {
    alert = {
        topic: 'High temperature',
        payload: 'Room temperature is ' + d.temperature.toFixed(1) + ' °C (limit 35 °C)'
    };
}
context.set('alerted', hot);

// Activity log: report state changes only
const events = [];
const prev = context.get('prev');
const ev = (text, level) => events.push({ topic: 'event', payload: text, level: level });
if (!prev) {
    ev('First telemetry received from the ESP32', 'info');
} else {
    if (prev.ac !== d.ac)
        ev('Compressor ' + d.ac + (hasT ? ' at ' + d.temperature.toFixed(1) + ' °C' : ''), d.ac === 'ON' ? 'ok' : 'info');
    if (prev.mode !== d.mode) ev('Mode changed to ' + d.mode, 'info');
    if (prev.setpoint !== d.setpoint) ev('Setpoint set to ' + d.setpoint.toFixed(1) + ' °C', 'info');
}
if (alert) ev(alert.payload, 'alert');
context.set('prev', { ac: d.ac, mode: d.mode, setpoint: d.setpoint });

return [temp, hum, mode, power, sp, overview, chart, alert, events];

// ESP32 status: retained "online" / Last Will "offline"
// Output 1 -> overview state, output 2 -> activity log
const online = String(msg.payload).trim().toLowerCase() === 'online';
return [
    { topic: 'status', payload: online },
    { topic: 'event', payload: online ? 'Device online' : 'Device offline (Last Will)', level: online ? 'ok' : 'alert' }
];

// Merge status + telemetry into a single state object for the header template
const s = context.get('s') || { online: false, data: null, last: null };
if (msg.topic === 'status') {
    s.online = msg.payload === true;
} else if (msg.topic === 'telemetry') {
    s.data = msg.payload;
    s.last = Date.now();
    s.online = true;
}
context.set('s', s);
return { payload: s };

// Keep the last 12 events (commands, state changes, alerts) for the activity log
let log = context.get('log') || [];
let text, level;
switch (msg.topic) {
    case 'cmd_mode':     text = 'Command sent: mode ' + msg.payload; level = 'cmd'; break;
    case 'cmd_power':    text = 'Command sent: power ' + msg.payload; level = 'cmd'; break;
    case 'cmd_setpoint': text = 'Command sent: setpoint ' + Number(msg.payload).toFixed(1) + ' °C'; level = 'cmd'; break;
    case 'event':        text = msg.payload; level = msg.level || 'info'; break;
    default: return null;
}
log.unshift({ t: Date.now(), text: text, level: level });
log = log.slice(0, 12);
context.set('log', log);
return { payload: log };
